import{_ as e,o,c as a,ae as d}from"./chunks/framework.DQC_QtFV.js";const g=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/troubleshooting.md","filePath":"en/guide/troubleshooting.md","lastUpdated":1793162416000}'),r={name:"en/guide/troubleshooting.md"};function n(s,t,h,i,l,c){return o(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Symptom</th><th>What it means</th></tr></thead><tbody><tr><td><code>error: no QQ source: set exactly one of ...</code></td><td>neither <code>QQ_DEB_URL</code> nor a mounted deb was given; see <a href="./first-start.html">First start</a></td></tr><tr><td><code>error: sha256 mismatch: expected ... got ...</code></td><td>the deb is not the pinned build; get the right file</td></tr><tr><td><code>error: both QQ_DEB_URL and the mounted deb ... are set</code></td><td>remove one of the two</td></tr><tr><td>The live view stays on the QR code</td><td>that is correct: a QR login is manual and yours to do</td></tr><tr><td><code>db.key = &quot;missing&quot;</code></td><td>the key extraction has not finished. The log is <code>./logs/keyx.log</code> on the host (<code>/out/keyx.log</code> inside the container). The driver keeps watching, so the status turns to <code>&quot;ok&quot;</code> on its own once the key lands</td></tr><tr><td><code>db.key = &quot;invalid&quot;</code></td><td>the client changed its key, or the private copy no longer matches. Follow the re-extract steps on the QQ page</td></tr><tr><td>The panel&#39;s pages answer 502</td><td>the driver or the bot is not up yet; check <code>docker compose logs qq bot</code></td></tr><tr><td>The bot starts no turn at all</td><td>look at 概览&#39;s 待处理 first: at least one admin and one conversation in the allow list are both required</td></tr><tr><td>Not one message goes out</td><td>the outbound review fails closed when Jev is unreachable. Check its state on <a href="./console/models.html">Models</a> and set the key</td></tr><tr><td>The sandbox cannot install a skill or reach a source</td><td>the domain is not on the allow list. Look at 网络 on <a href="./console/safety.html">Safety</a>; deleting a wrong entry makes it judged again</td></tr><tr><td>A persona edit changed nothing</td><td>identity takes effect at the next window, or use 立即轮换 on the page</td></tr></tbody></table><h2 id="where-the-logs-are" tabindex="-1">Where the logs are <a class="header-anchor" href="#where-the-logs-are" aria-label="Permalink to &quot;Where the logs are&quot;">​</a></h2><ul><li>The panel&#39;s <a href="./console/logs.html">Logs</a> page: driver, bot and panel events, filterable and live.</li><li><code>./logs/</code> on the host: the <code>qq</code> container&#39;s own diagnostics, which <strong>may contain chat content</strong> - do not share them.</li></ul><h2 id="still-stuck" tabindex="-1">Still stuck <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck&quot;">​</a></h2><p>Bring these when you ask: the image tag (<code>PERSONAL_BOT_TAG</code> or <code>latest</code>), the output of <code>docker compose ps</code>, the tail of <code>./logs/qq.log</code> and <code>./logs/keyx.log</code> with chat content removed, and a screenshot of the panel&#39;s <a href="./console/">概览</a> (mock data is fine too).</p>',6)])])}const m=e(r,[["render",n]]);export{g as __pageData,m as default};
